const KEY='hocco-message-client-v3';
export function syncHeaderAvatar(){let p={};try{p=JSON.parse(localStorage.getItem(KEY)||'{}').profile||{}}catch{}const index=Math.max(0,Math.min(19,Number(String(p.avatar||'avatar-01').replace('avatar-',''))-1||0)),el=document.querySelector('#header-profile-avatar');if(el)el.style.backgroundPosition=`${index%5*25}% ${Math.floor(index/5)*100/3}%`;}
syncHeaderAvatar();window.addEventListener('storage',syncHeaderAvatar);window.addEventListener('hocco-profile-updated',syncHeaderAvatar);
const mark=()=>{const hash=location.hash.slice(1).split('/')[0]||'inicio',current=location.pathname.startsWith('/ir-alem/')?'empresas':hash;document.querySelectorAll('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===current))};mark();window.addEventListener('hashchange',mark);
const destinations=[['Assistir à HOCCO','/#assistir'],['Enviar mensagem para o vídeo','/#enviar'],['Comunidade e LIVE','/#comunidade'],['Empresas e descontos por cidade','/ir-alem/'],['Patrocinar a HOCCO','/ir-alem/#novo'],['Meu perfil e avatar','/cliente/#perfil'],['Acompanhar pagamento e pedido','/cliente/#acompanhar'],['Informações e políticas','/#informacoes']];
document.querySelector('#site-search')?.addEventListener('click',()=>{document.querySelector('dialog')?.remove();const dialog=document.createElement('dialog');dialog.innerHTML='<div class="dialog-head"><h2>Explore a HOCCO</h2><button class="close" type="button" aria-label="Fechar busca">×</button></div><label for="cinema-search">O que você procura?</label><input id="cinema-search" type="search" placeholder="Comunidade, empresas, pedido…"><div class="cinema-search-results"></div>';const results=dialog.querySelector('.cinema-search-results'),draw=value=>{const list=destinations.filter(([title])=>title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));results.replaceChildren(...list.map(([title,href])=>{const a=document.createElement('a');a.textContent=title+' →';a.href=href;a.onclick=()=>dialog.close();return a}));if(!list.length)results.textContent='Nenhuma área encontrada. Tente outra palavra.'};dialog.querySelector('input').addEventListener('input',e=>draw(e.target.value));dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);draw('');dialog.showModal();dialog.querySelector('input').focus()});
